using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace dot_battle_signal_bus.scripts.Core.Save
{
    using Godot;

    /// <summary>
    /// Implemented by any runtime object (unit, item, location) that can be
    /// serialized into scene state and regenerated by a factory on load.
    /// </summary>
    public interface ISaveable
    {
        /// <summary>Stable id used by the factory to re-create this object (e.g. "goblin_grunt").</summary>
        string SaveId { get; }

        /// <summary>Serializes RUNTIME state only (health, position, flags) — not static definition data.</summary>
        Godot.Collections.Dictionary ToSaveData();

        /// <summary>Restores runtime state previously produced by <see cref="ToSaveData"/>.</summary>
        void LoadSaveData(Godot.Collections.Dictionary data);
    }
}
